// ReorderAchievements is the resolver for the reorderAchievements field.
func (r *mutationResolver) ReorderAchievements(ctx context.Context, projectID string, achievementIds []string) ([]model.Achievement, error) {
	userID, ok := middleware.GetUserID(ctx)
	if !ok || userID == "" {
		return nil, fmt.Errorf("user not authenticated")
	}

	// Check authorization
	if !r.RoleService.CanManageProject(ctx, userID, projectID) {
		return nil, fmt.Errorf("unauthorized to manage achievements in this project")
	}

	// Update sort_order for each achievement
	for i, achievementID := range achievementIds {
		err := r.DB.Queries.UpdateAchievementSortOrder(ctx, sqlc.UpdateAchievementSortOrderParams{
			ID:        achievementID,
			SortOrder: int32(i),
		})
		if err != nil {
			return nil, fmt.Errorf("failed to update achievement sort order: %w", err)
		}
	}

	// Invalidate cache for project and all affected achievements
	r.Cache.InvalidateProject(projectID)
	for _, achievementID := range achievementIds {
		r.Cache.InvalidateAchievement(achievementID)
		r.Loaders.AchievementByIDLoader.Clear(ctx, achievementID)
	}

	// Load and return reordered achievements with translations
	achievements := make([]model.Achievement, 0, len(achievementIds))
	for _, achievementID := range achievementIds {
		achievement, err := r.LoadAchievementWithTranslation(ctx, achievementID)
		if err != nil {
			return nil, fmt.Errorf("failed to load achievement: %w", err)
		}
		achievements = append(achievements, achievement)
	}

	return achievements, nil
}

// AwardAchievement is the resolver for the awardAchievement field.
func (r *mutationResolver) AwardAchievement(ctx context.Context, userID string, achievementID string) (model.Achievement, error) {
	// Load achievement via caching loader
	achievementThunk := r.Loaders.AchievementByIDLoader.Load(ctx, achievementID)
	achievement, err := achievementThunk()
	if err != nil {
		return nil, fmt.Errorf("failed to load achievement: %w", err)
	}

	// Check if achievement is awardable based on awardable_from timestamp
	if err := isAchievementAwardable(getAchievementAwardableFrom(achievement)); err != nil {
		return nil, err
	}

	projectID := getAchievementProjectID(achievement)
	eventID := getAchievementEventID(achievement)

	// Award achievement to user (will return error if already awarded)
	if err := r.DB.Queries.AwardUserAchievement(ctx, sqlc.AwardUserAchievementParams{
		UserID:        userID,
		AchievementID: achievementID,
	}); err != nil {
		return nil, fmt.Errorf("failed to award achievement: %w", err)
	}

	// Invalidate user cache
	r.Cache.InvalidateUser(userID)
	r.Cache.InvalidateAchievement(achievementID)
	// Invalidate achievedAt timestamp cache for this user/achievement
	r.Cache.Delete(cache.UserAchievementTimestampKey(userID, achievementID))

	// Invalidate project leaderboards (this will also invalidate project-level church, team, and superteam leaderboards)
	r.Cache.InvalidateProject(projectID)

	// Invalidate event leaderboards if achievement belongs to an event
	if eventID != nil && *eventID != "" {
		r.Cache.InvalidateEvent(*eventID)
	}

	// Send push notification in background with translated content
	if r.PushService != nil {
		go push.SendTranslatedAchievementNotification(r.PushService, r.Loaders, userID, getAchievementPushInfo(achievement))
	}

	// Notify Firestore listeners
	go r.FirebaseService.NotifyUserAchievements(context.Background(), userID)

	// Load and return the achievement with translation
	return r.LoadAchievementWithTranslation(ctx, achievementID)
}

// RevokeAchievement is the resolver for the revokeAchievement field.
func (r *mutationResolver) RevokeAchievement(ctx context.Context, userID string, achievementID string) (bool, error) {
	// First, get the achievement to know which project/event it belongs to
	achievementRow, err := r.DB.Queries.GetAchievementsByIDs(ctx, []string{achievementID})
	if err != nil || len(achievementRow) == 0 {
		return false, fmt.Errorf("failed to load achievement: %w", err)
	}

	projectID := achievementRow[0].ProjectID
	var eventID *string
	if achievementRow[0].EventID != nil && *achievementRow[0].EventID != "" {
		eventID = achievementRow[0].EventID
	}

	// Revoke achievement from user
	if err := r.DB.Queries.RevokeUserAchievement(ctx, sqlc.RevokeUserAchievementParams{
		UserID:        userID,
		AchievementID: achievementID,
	}); err != nil {
		return false, fmt.Errorf("failed to revoke achievement: %w", err)
	}

	// Delete score journal entry for this achievement
	if err := r.DB.Queries.DeleteScoreJournalByAchievement(ctx, sqlc.DeleteScoreJournalByAchievementParams{
		UserID:        userID,
		AchievementID: achievementID,
	}); err != nil {
		return false, fmt.Errorf("failed to delete score journal entry: %w", err)
	}

	// Invalidate user cache
	r.Cache.InvalidateUser(userID)
	r.Cache.InvalidateAchievement(achievementID)
	// Invalidate achievedAt timestamp cache for this user/achievement
	r.Cache.Delete(cache.UserAchievementTimestampKey(userID, achievementID))

	// Invalidate project leaderboards
	r.Cache.InvalidateProject(projectID)

	// Invalidate event leaderboards if achievement belongs to an event
	if eventID != nil {
		r.Cache.InvalidateEvent(*eventID)
	}

	// Notify Firestore listeners
	go r.FirebaseService.NotifyUserAchievements(context.Background(), userID)

	return true, nil
}

